        "lore": "Bị giằng xé giữa quyền năng thần thánh và thân xác phàm trần, Morgana đã trói buộc đôi cánh của mình để chọn lấy nhân tính, và chọn cách giáng nỗi đau, sự cay đắng của bản thân lên những kẻ bất trung và biến chất. Cô mặc kệ những luật lệ hay truyền thống mà cô cho rằng bất công, và chính bên trong bóng tối nơi Demacia, cô chiến đấu vì sự thật—dù những kẻ khác luôn muốn kiểm soát nó—với những tấm khiên, hay những sợi xích làm từ lửa bóng tối. Trên tất cả mọi thứ, Morgana thật sự tin rằng những kẻ bị vương quốc trục xuất, hay những tên ngoại tặc một ngày nào đó sẽ trỗi dậy.",
